INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Pierwsze badanie stomatologiczne i kompleksowe planowanie leczenia',
'<p>Kompleksowe pierwsze badanie to wysłuchanie dolegliwości, zebranie wywiadu medycznego i stomatologicznego, kliniczna ocena jamy ustnej i otaczających tkanek oraz wspólna interpretacja wyłącznie tych zapisów, które uznano za niezbędne. Plan leczenia powstaje etapami na podstawie tych danych, priorytetów pacjenta i odpowiednich opcji.</p>
<p><img src="/assets/uploads/images/ts18-ilk-dis-muayenesi-gorusme.webp" alt="Wysłuchanie powodu zgłoszenia się i oczekiwań pacjenta podczas pierwszego badania" loading="lazy"  /></p>
<h2>Powód zgłoszenia i oczekiwania</h2>
<p>Ból, oczekiwania estetyczne, trudność w żuciu, braki zębowe, obecne uzupełnienia i priorytety zapisywane są słowami samego pacjenta. Pierwszym celem nie jest wybór zabiegu, lecz zrozumienie potrzeb i kryteriów decyzji.</p>
<h2>Wywiad medyczny i stomatologiczny</h2>
<p>Pytamy o choroby ogólne, alergie, możliwość ciąży, wcześniejsze operacje i leczenie, przyjmowane leki oraz dotychczasowe doświadczenia stomatologiczne. W razie potrzeby zasięga się opinii lekarza prowadzącego; pacjent nie odstawia leków samodzielnie. O planowaniu leczenia w ciąży przeczytasz na stronie <a href="/pl/hamilelikte-dis-tedavisi/">Leczenie stomatologiczne w ciąży</a>.</p>
<h2>Badanie zewnątrzustne i tkanek miękkich</h2>
<p>Systematycznie oceniane są symetria twarzy, ruchy żuchwy, węzły chłonne i inne niezbędne objawy zewnątrzustne oraz tkanki miękkie: wargi, policzki, język, podniebienie i dno jamy ustnej. Przy stwierdzeniu podejrzanej zmiany planowana jest dalsza ocena i niezbędne badania.</p>
<h2>Zęby i obecne uzupełnienia</h2>
<p>Na podstawie objawów klinicznych oceniane są podejrzenie <a href="/pl/dis-curugu-kompozit-dolgu/">próchnicy</a>, złamania i starcia, zmiany koloru, nadwrażliwość, ruchomość zębów, stan wypełnień, koron i mostów oraz obszary braków zębowych. W razie potrzeby dodawane są testy żywotności i inne badania pomocnicze.</p>
<p><img src="/assets/uploads/images/ts18-kapsamli-agiz-dis-muayenesi.webp" alt="Systematyczne badanie zębów, dziąseł i tkanek jamy ustnej" loading="lazy"  /></p>
<h2>Ocena dziąseł i przyzębia</h2>
<p>Oceniane są płytka i kamień, krwawienie, recesje dziąseł, głębokość kieszonek, tkanki podporowe i wskaźniki ryzyka. Zdrowie dziąseł może zmienić kolejność leczenia przed zabiegami implantologicznymi, protetycznymi lub estetycznymi.</p>
<h2>Jak wspólnie wykorzystuje się dane z badania?</h2>
<table>
<thead><tr><th>Zapis</th><th>Wkład</th><th>Zasada stosowania</th></tr></thead>
<tbody>
<tr><td>Badanie kliniczne</td><td>Objawy dotyczące zębów, dziąseł, tkanek miękkich, stawu i zgryzu</td><td>Ocena podstawowa, której zakres ustala się u każdego pacjenta według potrzeb</td></tr>
<tr><td>Zapis radiologiczny</td><td>Ocena niewidocznych gołym okiem korzeni, kości i powierzchni stycznych</td><td>Wyłącznie zdjęcie niezbędne według wywiadu, wcześniejszych zapisów i objawów klinicznych</td></tr>
<tr><td>Zdjęcia / skan cyfrowy</td><td>Zapis pomocny w udokumentowaniu stanu wyjściowego, łuku zębowego i zgryzu</td><td>W zależności od rodzaju leczenia i potrzeb planowania; sam w sobie nie jest rozpoznaniem</td></tr>
</tbody>
</table>
<p><strong>Ważne:</strong> zdjęcie panoramiczne, tomografia, fotografie czy skan cyfrowy nie są automatycznym pakietem dla każdego pacjenta. Oceniana jest aktualność i wartość diagnostyczna wcześniejszych zapisów; nowy zapis wykonuje się tylko przy wskazaniach klinicznych.</p>
<p><img src="/assets/uploads/images/ts18-klinik-radyografik-dijital-degerlendirme.webp" alt="Wspólna ocena zapisów klinicznych, radiologicznych i cyfrowych" loading="lazy"  /></p>
<h2>Zgryz, staw i funkcja</h2>
<p>Oceniane są kontakty zębowe, warunki żucia, otwieranie ust, dolegliwości stawowe i mięśniowe, zaciskanie i zgrzytanie oraz objawy starcia. Każdy dźwięk czy starcie same w sobie nie oznaczają choroby ani potrzeby szyny.</p>
<h2>Dobór obrazowania</h2>
<p>Zdjęcie skrzydłowo-zgryzowe, przyzębne, panoramiczne lub obrazowanie trójwymiarowe dobiera się na podstawie objawów badania i planowanego zabiegu. Nie u każdego pacjenta stosuje się tomografię; oczekiwana korzyść diagnostyczna ważona jest z narażeniem na promieniowanie.</p>
<h2>Rola zapisów cyfrowych</h2>
<p>Zapisy ze skanera wewnątrzustnego, standardowe fotografie i modele cyfrowe mogą pomóc w udokumentowaniu stanu wyjściowego, zgryzu i planu odtwórczego. Wynik z oprogramowania nie zastępuje badania lekarskiego ani weryfikacji klinicznej.</p>
<h2>Rozpoznanie i ocena ryzyka</h2>
<p>Wspólnie rozpatrywane są próchnica, choroba przyzębia, problemy miazgi i okołowierzchołkowe, ryzyko złamania, higiena, palenie, odżywianie i nawyki pielęgnacyjne. Dla objawów niedających się rozstrzygnąć planowana jest obserwacja lub badania dodatkowe.</p>
<h2>Etapowy plan leczenia</h2>
<ol>
<li>Opanowanie ostrego bólu i infekcji</li>
<li>Zatrzymanie choroby i podstawowe zdrowie dziąseł</li>
<li>Ostateczne etapy odtwórcze, chirurgiczne lub protetyczne</li>
<li>Pielęgnacja i indywidualnie ustalony odstęp kontroli</li>
</ol>
<p>Sytuacja kliniczna może zmienić tę kolejność. To, co zawiera plan i jak jest aktualizowany, opisano na stronie <a href="/pl/tedavi-plani-ve-surec/">Plan leczenia i przebieg</a>.</p>
<p><img src="/assets/uploads/images/ts18-asamali-tedavi-plani-ve-bilgilendirme.webp" alt="Wyjaśnianie pacjentowi etapowego planu leczenia" loading="lazy"  /></p>
<h2>Opcje i przebieg</h2>
<p>W zrozumiały sposób omawiane są cel każdej możliwej opcji, jej istotne korzyści i ryzyka, alternatywy, możliwe skutki zaniechania leczenia oraz przewidywany czas i zakres. Plan może być aktualizowany na podstawie nowych objawów klinicznych lub reakcji na gojenie. Świadoma zgoda to nie tylko podpis; to proces zrozumiałego informowania i możliwości zadawania pytań.</p>
<h2>Najczęstsze pytania</h2>
<p><strong>Czy leczenie wykonuje się już podczas pierwszego badania?</strong><br>Nie zawsze. Priorytetem jest ocena i bezpieczne planowanie. Ostry ból lub odpowiedni prosty zabieg mogą zostać wykonane tego samego dnia, jeśli pozwala na to czas i uzyskano zgodę. Leczenie kompleksowe najczęściej zaczyna się po planowaniu.</p>
<p><strong>Czy od każdego pacjenta wymaga się zdjęcia panoramicznego?</strong><br>Nie. Rodzaj i moment obrazowania ustala się na podstawie wywiadu, badania klinicznego, wcześniejszych zdjęć i planowanego zabiegu. Jeśli dotychczasowe zapisy wystarczają, nie powtarza się ich bez potrzeby.</p>
<p><strong>Jak ustala się priorytety w planie leczenia?</strong><br>Najpierw stany nagłe i opanowanie infekcji; po zakończeniu etapów podstawowych, takich jak kontrola dziąseł i próchnicy, planowane są ostateczne odbudowy, implanty i protetyka lub zabiegi estetyczne.</p>
<p><strong>Czy mogę przynieść posiadane zapisy po drugą opinię?</strong><br>Tak. Zdjęcia RTG, raporty, informacje o implantach i zapisy wcześniejszego leczenia mogą pomóc w ocenie. Jeśli jednak ich aktualność lub jakość jest niewystarczająca, może być potrzebny dodatkowy zapis.</p>
<h2>Ocena lokalna</h2>
<p>W naszym gabinecie na styku Beylikdüzü i Esenyurt pierwsze badanie traktowane jest jako kompleksowy proces planowania, w którym wspólnie oceniane są dolegliwość, wywiad medyczny, zdrowie zębów i dziąseł, zgryz oraz wyłącznie niezbędne zapisy kliniczne i cyfrowe.</p>
<p><a href="/pl/acil-dis-agrisinda-ilk-24-saat/">Nagły ból zęba</a> &middot; <a href="/pl/tedavi-plani-ve-surec/">Plan leczenia i przebieg</a> &middot; <a href="/pl/dental-implant-tedavisi/">Leczenie implantami zębowymi</a> &middot; <a href="/pl/iletisim">Wizyta i kontakt</a></p>',
'Poznaj wywiad medyczny, ocenę dziąseł i zgryzu, niezbędne zdjęcia RTG, zapisy cyfrowe i etapowy plan leczenia podczas pierwszego badania stomatologicznego.',
'Pierwsze badanie stomatologiczne i plan leczenia | MSc. Dt. Mehmet Taş',
'PL' FROM pages WHERE link = 'ilk-dis-muayenesi-tedavi-planlamasi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Plan leczenia i przejrzystość procesu: co decyduje o jego zakresie?',
'<p>W leczeniu stomatologicznym niepewność często budzi większy niepokój niż samo leczenie. Gdy po badaniu na piśmie przekazuje się, jakie zabiegi zostaną wykonane, w ilu etapach się zakończą i w jakiej kolejności będą przebiegać, pacjent podejmuje decyzję świadomie. Ta strona wyjaśnia, jak przebiega proces, jeszcze przed zgłoszeniem się do gabinetu.</p>
<p><img src="/assets/uploads/images/ts90-01-tedavi-plani-gorusmesi.webp" alt="Lekarz omawia plan leczenia z pacjentem" loading="lazy"  /></p>
<h2>Co zawiera plan leczenia?</h2>
<table>
<thead><tr><th>Część</th><th>Opis</th></tr></thead>
<tbody>
<tr><td>Objawy kliniczne</td><td>Stan stwierdzony po badaniu i niezbędnym obrazowaniu.</td></tr>
<tr><td>Proponowane zabiegi</td><td>Jaki zabieg proponuje się dla którego zęba, w zrozumiałej formie.</td></tr>
<tr><td>Alternatywy</td><td>Inne podejścia możliwe przy tym samym problemie i różnice między nimi.</td></tr>
<tr><td>Etapy i kolejność</td><td>Który zabieg należy wykonać najpierw i dlaczego.</td></tr>
<tr><td>Przewidywany przebieg</td><td>Przybliżona liczba wizyt i spodziewane okresy oczekiwania na gojenie.</td></tr>
<tr><td>Co, jeśli się tego nie zrobi?</td><td>Spodziewany przebieg w razie odłożenia leczenia.</td></tr>
<tr><td>Potrzeby pielęgnacyjne</td><td>Oczekiwania dotyczące kontroli i codziennej pielęgnacji po leczeniu.</td></tr>
</tbody>
</table>
<p>W planach kompleksowych informacje te przekazywane są obok objaśnień ustnych także na piśmie; pacjent ma czas na przemyślenie i zadanie pytań.</p>
<h2>Co decyduje o zakresie planu?</h2>
<p>Plan leczenia dwóch osób z tą samą dolegliwością może być różny. Główne czynniki decydujące o zakresie:</p>
<ul>
<li>Rodzaj problemu, jego rozległość i stopień zaawansowania</li>
<li>Pozostałe zdrowe tkanki zęba oraz stan podparcia dziąsłowego i kostnego</li>
<li>Warunki zgryzowe, nawyk zaciskania i zgrzytania</li>
<li>Stan ogólny zdrowia, przyjmowane leki, palenie tytoniu</li>
<li>Nawyki higieniczne i możliwość przychodzenia na kontrole</li>
<li>Wybrana metoda, użyty materiał i etap laboratoryjny</li>
<li>Potrzeba zabiegów przygotowawczych (leczenie dziąseł, augmentacja kości, przygotowanie ortodontyczne itp.)</li>
</ul>
<p>Bez badania nie da się stworzyć planu. Kategoryczne informacje o leczeniu i jego zakresie udzielone przez telefon, wiadomość lub na podstawie zdjęcia nie są wiarygodne. Wstępna rozmowa daje jedynie ogólne wyobrażenie; plan powstaje po badaniu klinicznym i niezbędnym obrazowaniu.</p>
<p><img src="/assets/uploads/images/ts90-03-muayene-ve-degerlendirme.webp" alt="Wspólne przeprowadzenie badania i oceny radiologicznej" loading="lazy"  /></p>
<h2>Planowanie etapowe i kolejność priorytetów</h2>
<p>W leczeniu kompleksowym nie wszystko wykonuje się jednocześnie. Ogólnie stosowana kolejność jest następująca:</p>
<table>
<thead><tr><th>Etap</th><th>Zawartość</th></tr></thead>
<tbody>
<tr><td>1 — Nagły</td><td>Sytuacje niecierpiące zwłoki: ból, infekcja, obrzęk i uraz.</td></tr>
<tr><td>2 — Zatrzymanie choroby</td><td><a href="/pl/dis-curugu-kompozit-dolgu/">Leczenie próchnicy</a>, leczenie dziąseł, uporządkowanie higieny jamy ustnej.</td></tr>
<tr><td>3 — Odbudowa</td><td>Wypełnienia, korony, <a href="/pl/kanal-tedavisi/">leczenie kanałowe</a>, <a href="/pl/dental-implant-tedavisi/">uzupełnienie braków zębowych</a>.</td></tr>
<tr><td>4 — Estetyka</td><td>Zabiegi estetyczne, które nie są konieczne; po rozwiązaniu problemów zdrowotnych.</td></tr>
<tr><td>5 — Profilaktyka i obserwacja</td><td>Regularne kontrole, oczyszczanie, w razie potrzeby szyna nocna.</td></tr>
</tbody>
</table>
<p>Kolejność ta ma zapewnić, że podłoże, na którym budowana jest praca, będzie solidne. Długofalowy wynik estetycznej odbudowy wykonanej przy utrzymującym się zapaleniu dziąseł może ucierpieć.</p>
<p><img src="/assets/uploads/images/ts90-02-asamali-planlama.webp" alt="Schemat przedstawiający podział planu leczenia na etapy" loading="lazy"  /></p>
<h2>Czy plan może się zmienić?</h2>
<p>Tak. W stomatologii część danych ujawnia się dopiero w trakcie zabiegu: na przykład głębokość próchnicy okazuje się dokładnie podczas jej usuwania i może pojawić się potrzeba leczenia kanałowego. W takich sytuacjach przed kontynuacją pacjent jest informowany i wyraża zgodę. Aktualizacja planu nie oznacza, że pierwotna ocena była błędna.</p>
<h2>Ubezpieczenie społeczne (SGK) a leczenie stomatologiczne</h2>
<p>Uprawnienia do leczenia stomatologicznego w ramach Instytucji Ubezpieczeń Społecznych różnią się w zależności od rodzaju placówki. Usługi z zakresu zdrowia jamy ustnej świadczone są w publicznych placówkach ochrony zdrowia i w placówkach mających umowę z SGK, w zakresie określonym przepisami.</p>
<p><strong>Nasz gabinet nie ma umowy z Instytucją Ubezpieczeń Społecznych.</strong> Informacja ta jest tu podana wprost, ponieważ należy ją znać przed umówieniem wizyty. W razie zmiany przepisów lub statusu umowy ta sekcja zostanie zaktualizowana.</p>
<h2>Pytania, które możesz zadać lekarzowi</h2>
<ul>
<li>Jakie zabiegi są proponowane w moim przypadku i dlaczego?</li>
<li>Jakie są alternatywy tego leczenia? Czym się różnią?</li>
<li>Co należy zrobić teraz, a co może poczekać?</li>
<li>Ile wizyt jest przewidywanych? Jaki będzie odstęp między nimi?</li>
<li>Co jest normalne po zabiegu i w jakiej sytuacji mam zadzwonić?</li>
<li>Co się stanie, jeśli nie podejmę tego leczenia?</li>
<li>Jaka pielęgnacja i jakie kontrole będą potem potrzebne?</li>
<li>Czy mogę uzyskać informacje o użytym materiale?</li>
<li>Jak zostanę poinformowany, jeśli plan zmieni się w trakcie leczenia?</li>
</ul>
<h2>Twoje dane osobowe</h2>
<p>Informacje uzyskane podczas badania, obrazowania i leczenia są danymi osobowymi szczególnej kategorii. Cel ich przetwarzania, czas przechowywania i przysługujące Ci prawa opisano w <a href="/pl/sayfa/kvkk-aydinlatma-metni">informacji o ochronie danych osobowych</a>. Poprzez formularz wizyty nie są wymagane szczegółowe dane zdrowotne ani obrazy; w razie potrzeby bezpieczny sposób przekazania wskazywany jest osobno.</p>
<h2>Najczęstsze pytania</h2>
<p><strong>Czy mogę poznać zakres leczenia przez telefon?</strong><br>Ponieważ zakresu leczenia nie da się ustalić bez badania, przez telefon nie udziela się kategorycznych informacji. Po badaniu indywidualny plan przekazywany jest na piśmie.</p>
<p><strong>Czy mogę wziąć czas na przemyślenie planu leczenia?</strong><br>Tak. Jeśli nie ma sytuacji nagłej, jest naturalne, że poświęcisz czas na ocenę planu. Pytania możesz zadać również później.</p>
<p><strong>Czy mogę poprosić o opinię innego lekarza?</strong><br>Tak. Uzyskanie drugiej opinii jest prawem pacjenta. Na życzenie Twoje zapisy mogą zostać udostępnione.</p>
<p><strong>Co się dzieje, gdy plan zmienia się w trakcie leczenia?</strong><br>Przed kontynuacją sytuacja jest wyjaśniana, przedstawiane są opcje i uzyskiwana jest Twoja zgoda.</p>
<p><strong>Co zabrać na wizytę?</strong><br>Dokument tożsamości, posiadane wcześniejsze zdjęcia RTG i zapisy leczenia, listę przyjmowanych leków oraz informacje o znanych chorobach i alergiach. Jeśli masz opinię od innego lekarza, weź ją ze sobą.</p>
<p><strong>Czy mogę otrzymać fakturę i dokumenty?</strong><br>Wykonane zabiegi są dokumentowane zgodnie z przepisami. Na życzenie wydawana jest kopia Twoich zapisów leczenia.</p>
<h2>Ocena lokalna</h2>
<p>W naszym gabinecie na styku Beylikdüzü i Esenyurt plan leczenia powstaje na podstawie wspólnej oceny badania klinicznego, niezbędnego obrazowania i oczekiwań pacjenta, a następnie jest z nim omawiany.</p>
<p><a href="/pl/dental-implant-tedavisi/">Leczenie implantami zębowymi</a> &middot; <a href="/pl/kanal-tedavisi/">Leczenie kanałowe</a> &middot; <a href="/pl/sayfa/kvkk-aydinlatma-metni">Ochrona danych osobowych</a> &middot; <a href="/pl/iletisim">Wizyta i kontakt</a></p>',
'Co zawiera plan leczenia i co decyduje o jego zakresie? Co warto wiedzieć przed wizytą i jakie pytania zadać.',
'Plan leczenia i przejrzystość procesu | MSc. Dt. Mehmet Taş',
'PL' FROM pages WHERE link = 'tedavi-plani-ve-surec';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Co robić w pierwszych 24 godzinach przy nagłym bólu zęba?',
'<p><strong>Boli Cię teraz?</strong> <a href="tel:+905435588519">+90 543 558 85 19</a> &middot; <a href="https://wa.me/905435588519" target="_blank" rel="noopener">WhatsApp</a> &middot; <a href="https://www.google.com/maps/dir/?api=1&amp;destination=41.0173894%2C28.6465901" target="_blank" rel="noopener">Dojazd</a></p>
<p>Silny ból zęba najczęściej nie przechodzi sam; jego zmniejszenie nie oznacza, że problem zniknął. Celem pierwszych 24 godzin jest bezpieczne opanowanie bólu i jak najszybsze umówienie wizyty diagnostycznej. Poniższe zalecenia mają charakter informacyjny i nie zastępują badania.</p>
<h2>Co można zrobić od razu</h2>
<ul>
<li>Jamę ustną można delikatnie przepłukać letnią wodą.</li>
<li>Jeśli w bolesnym miejscu utkwił pokarm, można spróbować ostrożnie usunąć go nicią dentystyczną.</li>
<li>Zimno na policzek od zewnątrz (lód owinięty w tkaninę, z przerwami co 10–15 minut) może pomóc zmniejszyć obrzęk i ból.</li>
<li>Spanie z głową uniesioną nieco wyżej niż tułów może przynieść ulgę, zwłaszcza przy nasilającym się w nocy pulsującym bólu.</li>
<li>Jeśli rozważasz lek przeciwbólowy, wybierz preparat wcześniej zalecony przez lekarza lub farmaceutę i niemający u Ciebie przeciwwskazań, nie przekraczając dawki podanej na opakowaniu.</li>
</ul>
<p><img src="/assets/uploads/images/ts83-05-soguk-uygulama.webp" alt="Przykładanie zimnego okładu owiniętego w tkaninę od zewnątrz policzka przy bólu zęba" loading="lazy"  /></p>
<h2>Czego unikać</h2>
<ul>
<li><strong>Nie stosuj antybiotyku bez recepty.</strong> Antybiotyk nie usuwa źródła bólu; tymczasowo maskuje obraz, utrudnia rozpoznanie, a niepotrzebne stosowanie sprzyja powstawaniu oporności.</li>
<li>Nie przykładaj na bolący ząb lub dziąsło aspiryny, tabletek przeciwbólowych, wody kolońskiej, alkoholu ani octu; mogą one wywołać chemiczne oparzenie dziąsła.</li>
<li>Przy obrzęku nie stosuj ciepła; ciepły okład może ułatwić rozprzestrzenianie się stanu zapalnego.</li>
<li>Nie próbuj samodzielnie przebić ani wycisnąć ropnia.</li>
<li>Nie żuj twardych pokarmów po bolącej stronie.</li>
</ul>
<p><img src="/assets/uploads/images/ts83-06-kacinilmasi-gerekenler.webp" alt="Leki bez recepty i ciepły okład, których należy unikać przy bólu zęba" loading="lazy"  /></p>
<h2>Objawy wymagające natychmiastowego zgłoszenia się</h2>
<p>Jeśli występuje którykolwiek z poniższych objawów, obraz nie dotyczy wyłącznie problemu z zębem; należy bez zwłoki udać się na <strong>najbliższy oddział ratunkowy</strong>. Nie należy czekać na wizytę w gabinecie stomatologicznym.</p>
<table>
<thead><tr><th>Objaw</th><th>Dlaczego jest to nagłe?</th></tr></thead>
<tbody>
<tr><td>Trudność w oddychaniu lub połykaniu</td><td>Obrzęk może zwężać drogi oddechowe. Zagraża to życiu, należy od razu wezwać pogotowie.</td></tr>
<tr><td>Rozlany obrzęk dna jamy ustnej lub szyi</td><td>Może wskazywać na postęp infekcji do głębokich przestrzeni szyi.</td></tr>
<tr><td>Obrzęk rozszerzający się wokół oka, zamykająca się powieka</td><td>Może sygnalizować postęp ku górze infekcji pochodzącej ze szczęki.</td></tr>
<tr><td>Wysoka gorączka, dreszcze, osłabienie</td><td>Może wskazywać, że infekcja przekroczyła granice miejscowe.</td></tr>
<tr><td>Niemożność otwarcia ust (szczękościsk)</td><td>Może świadczyć o zajęciu mięśni żucia i rozprzestrzenianiu się infekcji.</td></tr>
<tr><td>Niedające się zatrzymać krwawienie</td><td>Wymaga pilnej oceny, zwłaszcza u osób przyjmujących leki rozrzedzające krew.</td></tr>
</tbody>
</table>
<p><strong>W razie złamania zęba lub jego wybicia po urazie:</strong> trzymaj ząb za część koronową, nie pocieraj korzenia; przechowuj go w mleku, soli fizjologicznej lub ślinie i zgłoś się jak najszybciej. Czas ma tu kluczowe znaczenie. Szczegółowe wskazówki dla dzieci znajdziesz na stronie <a href="/pl/cocuklarda-dis-travmasi/">Urazy zębów u dzieci</a>.</p>
<h2>Co robi się w gabinecie?</h2>
<p><img src="/assets/uploads/images/ts83-01-acil-degerlendirme-gorusmesi.webp" alt="Ocena pacjenta przez lekarza przy zgłoszeniu z nagłym bólem zęba" loading="lazy"  /></p>
<table>
<thead><tr><th>Krok</th><th>Co się robi</th><th>Czego się spodziewać</th></tr></thead>
<tbody>
<tr><td>Szybka ocena</td><td>Pytamy o lokalizację, czas trwania, charakter bólu i czynniki wyzwalające</td><td>Ustalenie, czy konieczna jest pilna interwencja</td></tr>
<tr><td>Badanie kliniczne</td><td>Badane są ząb, dziąsło i otaczające tkanki; może zostać wykonany test żywotności</td><td>Ustalenie źródła bólu</td></tr>
<tr><td>Badanie radiologiczne</td><td>W razie potrzeby wykonywane jest zdjęcie przyzębne lub panoramiczne</td><td>Obrazowanie stanu korzenia i kości</td></tr>
<tr><td>Usunięcie bólu</td><td>W zależności od sytuacji: drenaż, <a href="/pl/kanal-tedavisi/">otwarcie kanału</a> lub wypełnienie tymczasowe</td><td>Opanowanie bólu</td></tr>
<tr><td>Przedstawienie planu</td><td>Omawiane są opcje leczenia docelowego i harmonogram</td><td>Pisemna informacja o kolejnych krokach</td></tr>
</tbody>
</table>
<p><img src="/assets/uploads/images/ts83-02-panoramik-rontgen-incelemesi.webp" alt="Analiza zdjęcia panoramicznego w celu ustalenia źródła bólu zęba" loading="lazy"  /></p>
<p>Przy zgłoszeniach nagłych priorytetem jest usunięcie bólu i opanowanie infekcji. Leczenie docelowe planuje się zwykle na kolejnych wizytach, po ustąpieniu ostrego obrazu; szczegóły znajdziesz na stronie <a href="/pl/tedavi-plani-ve-surec/">Plan leczenia i przebieg</a>.</p>
<p><img src="/assets/uploads/images/ts83-03-brosurle-bilgilendirme.webp" alt="Omawianie z pacjentem opcji leczenia na podstawie broszury" loading="lazy"  /></p>
<p><img src="/assets/uploads/images/ts83-04-takip-ve-kontrol-plani.webp" alt="Przedstawienie pacjentowi planu kontroli i obserwacji po leczeniu" loading="lazy"  /></p>
<h2>Dojazd i wizyta</h2>
<p>W naszym gabinecie na styku Beylikdüzü i Esenyurt przyjmujemy zgłoszenia nagłe; dotyczy to także pacjentów przyjeżdżających z Büyükçekmece i sąsiednich dzielnic. Kontakt telefoniczny lub przez WhatsApp przed przyjazdem jest ważny zarówno dla przygotowania kolejki, jak i dla wskazania, co robić po drodze.</p>
<p><strong>Poza godzinami pracy:</strong> nasz lekarz dyżurny przeprowadza pierwszą ocenę przy zgłoszeniach poza godzinami i nagłych oraz rozpoczyna leczenie. Jeśli występują wymienione wyżej objawy nagłe, nie należy czekać, lecz udać się na najbliższy oddział ratunkowy.</p>
<p><a href="tel:+905435588519">+90 543 558 85 19</a> &middot; <a href="https://wa.me/905435588519" target="_blank" rel="noopener">WhatsApp</a> &middot; <a href="https://www.google.com/maps/dir/?api=1&amp;destination=41.0173894%2C28.6465901" target="_blank" rel="noopener">Dojazd</a></p>
<h2>Najczęstsze pytania</h2>
<p><strong>Wziąłem lek przeciwbólowy i ból minął, czy mimo to mam przyjść?</strong><br>Tak. Lek przeciwbólowy tłumi jedynie sygnał bólowy, nie usuwa stanu, który go wywołał. Zwłaszcza gdy zajęty jest nerw zęba, ból może na jakiś czas zelżeć, a potem wrócić silniejszy. Zaleca się umówienie wizyty diagnostycznej.</p>
<p><strong>Czy jeśli zacznę antybiotyk, ból minie?</strong><br>Antybiotyk może zostać przepisany przez lekarza jako uzupełnienie leczenia przy niektórych infekcjach, ale sam w sobie nie jest rozwiązaniem i nie należy zaczynać go samodzielnie. Źródło bólu usuwa się najczęściej zabiegiem mechanicznym (otwarcie kanału, drenaż). Niepotrzebne stosowanie antybiotyków utrudnia rozpoznanie i sprzyja antybiotykooporności.</p>
<p><strong>Czy przy bólu zęba, który zaczął się w nocy, czekać do rana?</strong><br>Jeśli ból da się kontrolować lekiem i nie występują wymienione objawy nagłe, wizytę można umówić rano. Jeśli jednak pojawiają się obrzęk, gorączka, trudność w połykaniu lub oddychaniu, nie należy czekać do rana, lecz udać się na najbliższy oddział ratunkowy.</p>
<p><strong>Ból minął, ale na dziąśle jest mały pęcherzyk, czy to ważne?</strong><br>Taki pęcherzyk może wskazywać, że stan zapalny znalazł ujście. Zmniejszenie bólu nie oznacza wyleczenia; proces może postępować po cichu. Zaleca się umówienie wizyty diagnostycznej.</p>
<h2>Ocena lokalna</h2>
<p>W naszym gabinecie na styku Beylikdüzü i Esenyurt priorytetem przy zgłoszeniach nagłych jest bezpieczne usunięcie bólu i opanowanie infekcji. Docelowy plan leczenia powstaje wspólnie z pacjentem po ustąpieniu ostrego obrazu.</p>
<p><a href="/pl/agiz-dis-sagligi/">Zdrowie jamy ustnej i zębów</a> &middot; <a href="/pl/kanal-tedavisi/">Leczenie kanałowe</a> &middot; <a href="/pl/dis-curugu-kompozit-dolgu/">Próchnica i wypełnienie kompozytowe</a> &middot; <a href="/pl/iletisim">Wizyta i kontakt</a></p>',
'Co robić w pierwszych 24 godzinach przy silnym bólu zęba, czego unikać i przy jakich objawach zgłosić się bez zwłoki? Poradnik krok po kroku.',
'Nagły ból zęba: pierwsze 24 godziny | MSc. Dt. Mehmet Taş',
'PL' FROM pages WHERE link = 'acil-dis-agrisinda-ilk-24-saat';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Leczenie stomatologiczne w ciąży: czy jest bezpieczne i kiedy je wykonać?',
'<p>W ciąży badanie, usuwanie kamienia, wypełnienia, leczenie kanałowe i konieczna ekstrakcja mogą być wykonywane przy zastosowaniu odpowiednich środków ostrożności. Takich sytuacji jak ból, obrzęk czy infekcja nie należy odkładać; nieleczona infekcja może stanowić większe ryzyko zarówno dla matki, jak i dla dziecka. Zabiegi estetyczne, które nie są konieczne, zwykle przekłada się na okres po porodzie. Ważne, by na każdej wizycie poinformować lekarza o ciąży i jej tygodniu.</p>
<h2>Co zmienia się w jamie ustnej w ciąży?</h2>
<table>
<thead><tr><th>Zmiana</th><th>Opis</th></tr></thead>
<tbody>
<tr><td>Ciążowe zapalenie dziąseł</td><td>Zmiany hormonalne czynią dziąsła bardziej wrażliwymi na płytkę; częste są zaczerwienienie, obrzęk i krwawienie przy szczotkowaniu.</td></tr>
<tr><td>Guzek na dziąśle</td><td>U części osób na dziąśle może powstać łatwo krwawiący, łagodny czerwony guzek. Najczęściej zmniejsza się po porodzie; mimo to powinien zostać oceniony przez lekarza.</td></tr>
<tr><td>Wzrost ryzyka próchnicy</td><td>Częste podjadanie, nudności i wymioty zwiększają kontakt z kwasem i osłabiają higienę, co może podnosić ryzyko próchnicy.</td></tr>
<tr><td>Erozja szkliwa</td><td>Powtarzające się wymioty mogą prowadzić do kwasowej erozji powierzchni zębów.</td></tr>
</tbody>
</table>
<p>Istnieją badania donoszące o związku między chorobą przyzębia u przyszłych matek a porodem przedwczesnym; nie wykazano jednak w sposób pewny, że leczenie dziąseł w ciąży zapobiega przedwczesnemu porodowi. Leczenie dziąseł jest ważne dla zdrowia jamy ustnej matki i w tym celu powinno być prowadzone.</p>
<h2>Planowanie według trymestrów</h2>
<table>
<thead><tr><th>Okres</th><th>Ogólne podejście</th></tr></thead>
<tbody>
<tr><td>I trymestr (tygodnie 1–13)</td><td>Badanie i oczyszczanie są możliwe. Ponieważ nudności mogą być nasilone, długie zabiegi, jeśli nie są pilne, można przełożyć na kolejny okres. Sytuacji nagłych się nie odkłada.</td></tr>
<tr><td>II trymestr (tygodnie 14–27)</td><td>Dla wielu przyszłych matek to najwygodniejszy okres. Potrzebne wypełnienia, <a href="/pl/kanal-tedavisi/">leczenie kanałowe</a> i leczenie dziąseł planuje się najczęściej właśnie wtedy.</td></tr>
<tr><td>III trymestr (po 28. tygodniu)</td><td>Konieczne leczenie jest możliwe; ponieważ jednak długie leżenie na plecach może powodować dyskomfort i spadek ciśnienia, wizyty są krótkie, a pozycja kontrolowana.</td></tr>
</tbody>
</table>
<p>To ogólne ramy; plan ustala się indywidualnie w zależności od przebiegu ciąży i zaleceń Twojego ginekologa.</p>
<h2>Na co zwraca się uwagę w gabinecie?</h2>
<p><img src="/assets/uploads/images/ts79-01-unit-pozisyonu.webp" alt="Ciężarna pacjentka na fotelu stomatologicznym, podparta i lekko obrócona na lewy bok" loading="lazy" /></p>
<table>
<thead><tr><th>Zagadnienie</th><th>Opis</th></tr></thead>
<tbody>
<tr><td>Informacja</td><td>Należy podać tydzień ciąży, przyjmowane witaminy i leki, ewentualną ciążę wysokiego ryzyka oraz zalecenia ginekologa.</td></tr>
<tr><td>Znieczulenie miejscowe</td><td>Środki znieczulające stosowane w stomatologii mogą być używane w ciąży w dawkach uznanych przez lekarza za odpowiednie. Leczenie z bólem może być większym obciążeniem niż zastosowanie znieczulenia.</td></tr>
<tr><td>Zdjęcia RTG</td><td>Wykonuje się je tylko wtedy, gdy są rzeczywiście niezbędne do rozpoznania. Dawka promieniowania przy zdjęciach stomatologicznych jest bardzo mała, a zdjęcia wykonuje się z zachowaniem środków ochronnych.</td></tr>
<tr><td>Leki</td><td>Jeśli potrzebny jest lek przeciwbólowy lub antybiotyk, wybiera się opcje uznane za bezpieczne w ciąży, w razie potrzeby po konsultacji z ginekologiem. Nie stosuj leków na własną rękę.</td></tr>
<tr><td>Pozycja</td><td>W zaawansowanej ciąży wygodniejsza jest pozycja półsiedząca z przechyleniem na lewo niż pełne leżenie na plecach. Przy zawrotach głowy, nudnościach lub duszności od razu powiedz lekarzowi.</td></tr>
<tr><td>Czas wizyty</td><td>Preferowane są krótkie wizyty z częstymi przerwami.</td></tr>
</tbody>
</table>
<p><img src="/assets/uploads/images/ts79-02-gebelik-bilgisi-paylasimi.webp" alt="Ciężarna pacjentka przekazuje dentyście informacje o ciąży i zdrowiu" loading="lazy" /></p>
<h2>Pielęgnacja w domu a nudności</h2>
<p><img src="/assets/uploads/images/ts79-03-bulanti-sonrasi-calkalama.webp" alt="Płukanie jamy ustnej wodą po nudnościach w ciąży" loading="lazy" /></p>
<p>Zaleca się szczotkowanie dwa razy dziennie pastą z fluorem i miękką szczoteczką oraz codzienne czyszczenie przestrzeni międzyzębowych. Nie przerywaj szczotkowania z powodu krwawienia dziąseł; krwawienie jest najczęściej oznaką odkładania się płytki i zmniejsza się przy regularnym, delikatnym czyszczeniu.</p>
<p>Po wymiotach zamiast od razu szczotkować, przepłucz usta wodą i odczekaj chwilę; zmiękczona kwasem powierzchnia szkliwa łatwiej ściera się szczoteczką. Jeśli szczotkowanie wywołuje nudności, spróbuj szczoteczki z małą główką i pasty o łagodniejszym smaku. Jeśli konieczne są częste przekąski, zamiast słodkich i lepkich produktów wybieraj ser, jogurt czy warzywa.</p>
<p><img src="/assets/uploads/images/ts79-04-yumusak-fircayla-fircalama.webp" alt="Delikatne szczotkowanie miękką szczoteczką przy wrażliwych dziąsłach w ciąży" loading="lazy" /></p>
<h2>Zabiegi, które można odłożyć</h2>
<p>Zabiegi estetyczne, takie jak <a href="/pl/dis-beyazlatma/">wybielanie zębów</a>, licówki czy korony, niekonieczna <a href="/pl/dental-implant-tedavisi/">chirurgia implantologiczna</a> i rozległe odnowy estetyczne planuje się zwykle po porodzie. Nie oznacza to, że zabiegi te są koniecznie szkodliwe; celem jest unikanie zbędnych leków i długich wizyt przy zabiegach niepilnych.</p>
<p><strong>Czego nie należy odkładać:</strong> silny ból zęba, obrzęk twarzy, ropień, gorączka, uraz i złamanie. W tych sytuacjach, niezależnie od tygodnia ciąży, należy zgłosić się bez zwłoki.</p>
<h2>Najczęstsze pytania</h2>
<p><strong>Czy w ciąży można znieczulić ząb?</strong><br>Tak. Środki znieczulające stosowane w stomatologii mogą być używane w ciąży w dawkach określonych przez lekarza. Koniecznie poinformuj o ciąży i ewentualnej szczególnej sytuacji.</p>
<p><strong>Czy w ciąży wykonuje się zdjęcia RTG zębów?</strong><br>Można je wykonać, jeśli są potrzebne do rozpoznania. Dawka przy zdjęciach stomatologicznych jest bardzo mała, a zdjęcia wykonuje się z zachowaniem środków ochronnych. Zdjęcie niekonieczne jest odkładane.</p>
<p><strong>Dziąsła krwawią mi przy szczotkowaniu, czy to normalne?</strong><br>W ciąży zdarza się to często, ale nie jest to stan, który należy zostawić. Kontynuuj delikatne i regularne szczotkowanie oraz czyszczenie przestrzeni międzyzębowych i umów się na kontrolę; w razie potrzeby można usunąć kamień nazębny.</p>
<p><strong>Czy w ciąży usuwa się zęby?</strong><br>Jeśli to konieczne, tak. Usunięcia zęba wywołującego infekcję lub silny ból nie należy odkładać. Planowanie odbywa się zgodnie z tygodniem ciąży i stanem ogólnym.</p>
<p><strong>Czy mogę leczyć zęby podczas karmienia piersią?</strong><br>Tak. Znieczulenie miejscowe i wypełnienia nie są przeszkodą w karmieniu. Jeśli potrzebne są leki, poinformuj lekarza, że karmisz.</p>
<h2>Ocena lokalna</h2>
<p>W naszym gabinecie na styku Beylikdüzü i Esenyurt planowanie leczenia przyszłych matek odbywa się na podstawie wspólnej oceny okresu ciąży, wyników badania klinicznego, stanu ogólnego zdrowia i zaleceń Twojego ginekologa. MSc. Dt. Mehmet Taş i jego zespół dostosowują czas wizyty i pozycję na fotelu do tygodnia Twojej ciąży.</p>
<p><a href="/pl/agiz-dis-sagligi/">Zdrowie jamy ustnej i zębów</a> · <a href="/pl/kanal-tedavisi/">Leczenie kanałowe</a> · <a href="/pl/iletisim">Wizyta i kontakt</a></p>',
'Czy w ciąży można leczyć zęby, jaki okres jest najodpowiedniejszy, dlaczego krwawią dziąsła, czy znieczulenie i RTG są bezpieczne? Poradnik dla przyszłych mam.',
'Leczenie stomatologiczne w ciąży | MSc. Dt. Mehmet Taş',
'PL' FROM pages WHERE link = 'hamilelikte-dis-tedavisi';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'Stomatologia dziecięca: pierwsze badanie, próchnica zębów mlecznych i profilaktyka',
'<p>Pierwsze badanie stomatologiczne dziecka zaleca się w ciągu sześciu miesięcy od wyrżnięcia pierwszego zęba mlecznego lub najpóźniej w pierwsze urodziny. Celem tej wizyty najczęściej nie jest leczenie; chodzi o ocenę ryzyka próchnicy, przekazanie rodzinie informacji o pielęgnacji i żywieniu odpowiednich do wieku oraz oswojenie dziecka z gabinetem. U dziecka, które poznało gabinet wcześnie, późniejsze leczenie zwykle łatwiej przeprowadzić.</p>
<p><img src="/assets/uploads/images/ts87-01-ilk-muayene-kucuk-cocuk.webp" alt="Pierwsze badanie małego dziecka na fotelu stomatologicznym" loading="lazy"  /></p>
<p>W naszym gabinecie małych pacjentów ocenia i leczy nasza specjalistka stomatologii dziecięcej.</p>
<h2>Dlaczego zęby mleczne są ważne?</h2>
<p>Zęby mleczne to nie tylko tymczasowy zestaw; pełnią funkcje w żuciu, rozwoju mowy i utrzymaniu miejsca dla zębów stałych. Do luki po wcześnie utraconym zębie mlecznym mogą przesunąć się zęby sąsiednie, zwężając miejsce potrzebne zębowi stałemu.</p>
<table>
<thead><tr><th>Funkcja</th><th>Opis</th></tr></thead>
<tbody>
<tr><td>Żucie i odżywianie</td><td>Bolący lub zepsuty ząb może ograniczać żucie i różnorodność diety dziecka.</td></tr>
<tr><td>Rozwój mowy</td><td>Zęby przednie uczestniczą w powstawaniu niektórych głosek.</td></tr>
<tr><td>Utrzymanie miejsca</td><td>Każdy ząb mleczny trzyma miejsce dla zęba stałego pod nim. Przy wczesnej utracie miejsce może się zwęzić.</td></tr>
<tr><td>Rozwój szczęk</td><td>Zrównoważone żucie wspiera rozwój szczęk i mięśni.</td></tr>
</tbody>
</table>
<h2>Jak zaczyna się i jak rozpoznać próchnicę zębów mlecznych?</h2>
<p>Szkliwo zęba mlecznego jest cieńsze niż stałego; dlatego <a href="/pl/dis-curugu-kompozit-dolgu/">próchnica</a> u niektórych dzieci może postępować szybciej. We wczesnym okresie może nie być bólu, dlatego regularne kontrole są ważne bez czekania na ból.</p>
<ul>
<li>Kredowobiałe plamy przy brzegu dziąsła (objaw początkowy)</li>
<li>Brązowo-czarne przebarwienie, zagłębienie na powierzchni</li>
<li>Nadwrażliwość na zimno, ciepło lub słodkie</li>
<li>Unikanie przez dziecko żucia jedną stroną</li>
<li>Obrzęk dziąsła, obrzęk twarzy lub gorączka — wtedy nie należy czekać</li>
</ul>
<p><img src="/assets/uploads/images/ts87-02-sut-disi-curuk-asamalari.webp" alt="Etapy próchnicy zęba mlecznego od początkowej plamy po stadium zaawansowane" loading="lazy"  /></p>
<p><strong>Butelka i karmienie nocne:</strong> słodkie napoje lub soki podawane z butelki podczas snu oraz częste karmienie nocne wiąże się z szybko postępującą próchnicą zębów przednich. Poza wodą nie należy podawać napojów przed snem i w jego trakcie.</p>
<h2>Higiena jamy ustnej i fluor według wieku</h2>
<p>Szczotkowanie zaczyna się w chwili pojawienia się pierwszego zęba. U małych dzieci szczotkuje rodzic; w wieku szkolnym, nawet gdy dziecko szczotkuje samo, kontrola i pomoc rodzica trwają nadal.</p>
<table>
<thead><tr><th>Wiek</th><th>Podejście</th></tr></thead>
<tbody>
<tr><td>Pierwszy ząb – 3 lata</td><td>Dwa razy dziennie, miękka szczoteczka z małą główką. Pasta z fluorem wielkości ziarnka ryżu (cienka smuga). Szczotkuje rodzic.</td></tr>
<tr><td>3 – 6 lat</td><td>Dwa razy dziennie, pasta z fluorem wielkości ziarnka grochu. Dziecko szczotkuje, rodzic dokańcza i nadzoruje. Uczymy wypluwania pasty, bez płukania.</td></tr>
<tr><td>6 lat i więcej</td><td>Szczotkowanie dwa razy dziennie, nić dentystyczna na powierzchniach stycznych. Nadzór rodzica trwa, stopniowo maleje.</td></tr>
<tr><td>Każdy wiek</td><td>Tubkę pasty trzyma się poza zasięgiem dziecka; pasty nie należy połykać.</td></tr>
</tbody>
</table>
<p>Odpowiednią ilość pasty i zapotrzebowanie na fluor ustala lekarz w zależności od wieku dziecka i jego ryzyka próchnicy.</p>
<p><img src="/assets/uploads/images/ts87-03-yasa-gore-macun-miktari.webp" alt="Ilość pasty do zębów według wieku: porównanie ziarnka ryżu i ziarnka grochu" loading="lazy"  /></p>
<h2>Zabiegi profilaktyczne</h2>
<table>
<thead><tr><th>Zabieg</th><th>Kiedy jest rozważany?</th></tr></thead>
<tbody>
<tr><td>Lakowanie bruzd</td><td>Gdy głębokie bruzdy na powierzchni żującej trzonowców trudno oczyścić; wykonuje się po wyrznięciu zęba, przy braku próchnicy.</td></tr>
<tr><td>Lakier fluorowy</td><td>Może być stosowany w gabinecie w określonych odstępach w zależności od oceny ryzyka próchnicy. U każdego dziecka częstość jest inna.</td></tr>
<tr><td>Poradnictwo żywieniowe</td><td>Przeglądane są częstość cukru, rytm przekąsek i wybór napojów.</td></tr>
<tr><td>Nauka szczotkowania</td><td>Technika pokazywana jest odpowiednio do sprawności manualnej i wieku dziecka; określana jest rola rodzica.</td></tr>
</tbody>
</table>
<p>Lakowanie bruzd, aplikacja fluoru, utrzymywacz przestrzeni i profilaktyczne wypełnienia żywicowe wykonywane są w całości w naszym gabinecie.</p>
<p><img src="/assets/uploads/images/ts87-04-fissur-orturucu.webp" alt="Lak szczelinowy nałożony na powierzchnię żującą trzonowca" loading="lazy"  /></p>
<h2>Utrata zęba i utrzymywacz przestrzeni</h2>
<p>Jeśli ząb mleczny zostanie utracony przedwcześnie z powodu próchnicy lub urazu, można rozważyć utrzymywacz przestrzeni, by ograniczyć przesuwanie się zębów sąsiednich. Nie jest on konieczny przy każdej wczesnej utracie; decyzja zależy od tego, który ząb został utracony, od wieku dziecka, etapu rozwoju zęba stałego pod nim i obrazu radiologicznego.</p>
<h2>Przygotowanie dziecka do wizyty</h2>
<ul>
<li>Zamiast szczegółowych, strasznych opowieści przed wizytą zaleca się przedstawienie jej w spokojnych ramach, np. jako „liczenie zębów”.</li>
<li>Dla zachowania zaufania ważne jest, by nie składać kategorycznych obietnic typu „nie będzie bolało” czy „nie będzie zastrzyku”.</li>
<li>Umówienie wizyty na porę, gdy dziecko jest wypoczęte, ułatwia współpracę.</li>
<li>Wcześniejsze negatywne doświadczenia, ewentualne potrzeby specjalne i przyjmowane leki należy zgłosić przed wizytą.</li>
</ul>
<p>U dzieci z wyraźnym lękiem stosuje się podejście stopniowego oswajania. U dzieci mających trudność we współpracy, bardzo małych lub wymagających rozległego leczenia zabieg wykonywany jest w sedacji; sedację przeprowadzamy w naszym gabinecie. W sytuacjach wymagających znieczulenia ogólnego leczenie odbywa się w naszych szpitalach partnerskich w obecności anestezjologa i również przez naszą specjalistkę stomatologii dziecięcej. Metoda ustalana jest wspólnie z rodziną po ocenie wieku dziecka, stanu ogólnego zdrowia i zakresu leczenia.</p>
<h2>Najczęstsze pytania</h2>
<p><strong>Kiedy po raz pierwszy zabrać dziecko do dentysty?</strong><br>Zaleca się w ciągu sześciu miesięcy od wyrżnięcia pierwszego zęba mlecznego, najpóźniej w pierwsze urodziny. Nawet bez dolegliwości wizyta ta służy ocenie ryzyka próchnicy i ustaleniu planu pielęgnacji.</p>
<p><strong>Ząb mleczny i tak wypadnie, czy leczyć jego próchnicę?</strong><br>Tak. Nieleczona próchnica może prowadzić do bólu, infekcji, problemów z odżywianiem i wczesnej utraty zęba; wczesna utrata może wpłynąć na miejsce zęba stałego.</p>
<p><strong>Czy pasta z fluorem jest bezpieczna dla dziecka?</strong><br>Stosowana w ilości odpowiedniej do wieku i pod nadzorem pasta z fluorem uznawana jest za korzystną w profilaktyce próchnicy. Ważne, by ilość była dostosowana do wieku i by pasta nie była połykana.</p>
<p><strong>Moje dziecko ma szpary między zębami, czy to problem?</strong><br>W uzębieniu mlecznym szpary są najczęściej zjawiskiem oczekiwanym i zapewniają miejsce zębom stałym. Ocena odbywa się jednak podczas badania.</p>
<p><strong>Czy ssanie palca lub smoczek psuje zęby?</strong><br>W zależności od czasu trwania i intensywności może wpływać na warunki zgryzowe. Przy utrzymującym się nawyku rozważa się sposób odzwyczajania odpowiedni do wieku.</p>
<p><strong>Czy stomatologia dziecięca i ortodoncja to to samo?</strong><br>Nie. Stomatologia dziecięca obejmuje próchnicę, profilaktykę i leczenie zębów mlecznych; ustawienie zębów i szczęk jest przedmiotem oceny ortodontycznej.</p>
<h2>Ocena lokalna</h2>
<p>W naszym gabinecie na styku Beylikdüzü i Esenyurt priorytetem u dzieci jest poznanie gabinetu w okresie bez bólu i wczesne wykrycie ryzyka próchnicy. Potrzebę leczenia planuje się na podstawie wspólnej oceny badania klinicznego, wieku dziecka, poziomu współpracy i niezbędnego obrazowania.</p>
<p><a href="/pl/agiz-dis-sagligi/">Zdrowie jamy ustnej i zębów</a> · <a href="/pl/dis-curugu-kompozit-dolgu/">Próchnica i wypełnienie kompozytowe</a> · <a href="/pl/cocuklarda-dis-travmasi/">Urazy zębów u dzieci</a> · <a href="/pl/kanal-tedavisi/">Leczenie kanałowe</a> · <a href="/pl/iletisim">Wizyta i kontakt</a></p>',
'Kiedy wykonać pierwsze badanie stomatologiczne u dziecka, dlaczego ważna jest próchnica zębów mlecznych, kiedy potrzebny jest fluor i utrzymywacz przestrzeni? Poradnik dla rodzin.',
'Stomatologia dziecięca | MSc. Dt. Mehmet Taş',
'PL' FROM pages WHERE link = 'cocuk-dis-hekimligi';

